//! The golden peer-wire fixtures (`tests/fixtures/peer_wire/<version>/`):
//! every frozen release's session still decodes, its signed entries still
//! verify byte for byte, every builtin fact kind is present and registered,
//! and the fixture files are append-only (MANIFEST hashes).
//!
//! The fixtures are what a release's own codec emits for deterministic
//! inputs, generated by `scripts/freeze-peer-wire` from
//! `tests/support/peer_wire_freeze.rs`; they are not a recorded live session.

use std::collections::BTreeSet;
use std::path::{Path, PathBuf};

use serde::Deserialize;
use serde_json::value::RawValue;
use sha2::{Digest, Sha256};

use herdr_threads::sync::envelope::{Envelope, WireEnvelope};
use herdr_threads::sync::facts::{
    FactRegistry, GenesisPayload, RetagPayload, invitation, membership, message, receipt, seat,
    thread,
};
use herdr_threads::sync::frame::PeerFrame;

use super::peer_wire_freeze;

/// Kinds a frozen release lists but this build intentionally does not
/// register. None today; list one here with the reason if it ever happens.
const PARKED: &[(&str, u32)] = &[];

fn fixtures_root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/peer_wire")
}

fn fixture_dirs() -> Vec<PathBuf> {
    let mut dirs: Vec<PathBuf> = std::fs::read_dir(fixtures_root())
        .expect("tests/fixtures/peer_wire exists")
        .map(|entry| entry.expect("dir entry").path())
        .filter(|path| path.is_dir())
        .collect();
    dirs.sort();
    dirs
}

fn name_of(dir: &Path) -> String {
    dir.file_name()
        .expect("fixture dir name")
        .to_string_lossy()
        .into_owned()
}

fn hex(bytes: &[u8]) -> String {
    bytes.iter().map(|b| format!("{b:02x}")).collect()
}

fn sha256_hex(bytes: &[u8]) -> String {
    hex(&Sha256::digest(bytes))
}

fn lines_of(path: &Path) -> Vec<String> {
    let text = std::fs::read_to_string(path).unwrap_or_else(|e| panic!("{}: {e}", path.display()));
    assert!(
        text.ends_with('\n'),
        "{} ends with a newline",
        path.display()
    );
    text.lines().map(str::to_owned).collect()
}

#[derive(Deserialize)]
struct SessionLine {
    dir: String,
    frame: Box<RawValue>,
}

#[derive(Deserialize)]
struct EnvelopeLine {
    label: String,
    canonical: String,
    wire: Box<RawValue>,
}

/// The `(kind, major)` list under `## Fact kinds` of a MANIFEST.
fn manifest_kinds(manifest: &str) -> BTreeSet<(String, u32)> {
    let mut kinds = BTreeSet::new();
    let mut in_section = false;
    for line in manifest.lines() {
        if line.starts_with("## ") {
            in_section = line == "## Fact kinds";
        } else if in_section && let Some(item) = line.strip_prefix("- ") {
            let (kind, major) = item.rsplit_once(" v").expect("`- kind vN` line");
            kinds.insert((kind.to_owned(), major.parse().expect("major number")));
        }
    }
    kinds
}

/// The `(hash, file)` pairs under `## Files` of a MANIFEST.
fn manifest_files(manifest: &str) -> Vec<(String, String)> {
    let mut files = Vec::new();
    let mut in_section = false;
    for line in manifest.lines() {
        if line.starts_with("## ") {
            in_section = line == "## Files";
        } else if in_section && !line.is_empty() {
            let (hash, name) = line.split_once("  ").expect("`<sha256>  <file>` line");
            files.push((hash.to_owned(), name.to_owned()));
        }
    }
    files
}

/// Decode `payload` into the typed payload of `kind`; an unlisted kind fails
/// by name so a new builtin cannot slip past the fixtures unchecked.
fn decode_payload(kind: &str, payload: &[u8]) -> Result<(), String> {
    fn parse<T: serde::de::DeserializeOwned>(payload: &[u8]) -> Result<(), String> {
        serde_json::from_slice::<T>(payload)
            .map(|_| ())
            .map_err(|e| e.to_string())
    }
    match kind {
        "node.genesis" => parse::<GenesisPayload>(payload),
        "node.retag" => parse::<RetagPayload>(payload),
        "seat.created" => parse::<seat::SeatCreatedPayload>(payload),
        "seat.retired" => parse::<seat::SeatRetiredPayload>(payload),
        "thread.created" => parse::<thread::ThreadCreatedPayload>(payload),
        "thread.register" => parse::<thread::ThreadRegisterPayload>(payload),
        "thread.direct" => parse::<thread::ThreadDirectPayload>(payload),
        "invitation.created" => parse::<invitation::InvitationCreatedPayload>(payload),
        "invitation.answered" => parse::<invitation::InvitationAnsweredPayload>(payload),
        "membership.joined" | "membership.left" => parse::<membership::MembershipPayload>(payload),
        "message.sent" => parse::<message::MessageSentPayload>(payload),
        "receipt.settled" => parse::<receipt::ReceiptSettledPayload>(payload),
        other => Err(format!("no payload decoder for kind {other}")),
    }
}

fn check_session(dir: &Path) -> Vec<Envelope> {
    let name = name_of(dir);
    let mut tags = BTreeSet::new();
    let mut forks_seen = false;
    let mut from_frames = Vec::new();
    for line in lines_of(&dir.join("session.jsonl")) {
        let parsed: SessionLine =
            serde_json::from_str(&line).unwrap_or_else(|e| panic!("{name} session line: {e}"));
        assert!(
            parsed.dir == "a>b" || parsed.dir == "b>a",
            "{name}: direction {}",
            parsed.dir
        );
        let frame = PeerFrame::decode(parsed.frame.get().as_bytes())
            .unwrap_or_else(|e| panic!("{name}: frame does not decode: {e}: {}", parsed.frame));
        assert!(
            !matches!(frame, PeerFrame::Unknown),
            "{name}: frame decodes to Unknown: {}",
            parsed.frame
        );
        let value: serde_json::Value = serde_json::from_str(parsed.frame.get()).expect("frame");
        tags.insert(value["t"].as_str().expect("frame tag").to_owned());
        match frame {
            PeerFrame::Hello(hello) => assert_eq!(hello.envelope, 1, "{name}: hello envelope"),
            PeerFrame::Have { forks, .. } => forks_seen |= !forks.is_empty(),
            PeerFrame::Entries { entries, .. } | PeerFrame::BranchEntries { entries, .. } => {
                from_frames.extend(entries.into_iter().map(|wire| {
                    Envelope::try_from(wire).unwrap_or_else(|e| panic!("{name}: frame entry: {e}"))
                }));
            }
            _ => {}
        }
    }
    let expected: BTreeSet<String> = [
        "hello",
        "auth",
        "accept",
        "have",
        "want",
        "entries",
        "credit",
        "ping",
        "pong",
        "seen",
        "unwant",
        "branch_want",
        "branch_entries",
        "branch_none",
        "close",
    ]
    .iter()
    .map(|t| (*t).to_owned())
    .collect();
    assert_eq!(tags, expected, "{name}: frame kinds in the session");
    assert!(forks_seen, "{name}: a have carries fork refs");
    from_frames
}

fn check_envelopes(dir: &Path, from_frames: &[Envelope]) -> BTreeSet<(String, u32)> {
    let name = name_of(dir);
    let mut pubkey = None;
    let mut kinds = BTreeSet::new();
    let mut labels = Vec::new();
    let mut envelopes = Vec::new();
    for line in lines_of(&dir.join("envelopes.jsonl")) {
        let parsed: EnvelopeLine =
            serde_json::from_str(&line).unwrap_or_else(|e| panic!("{name} envelope line: {e}"));
        let wire: WireEnvelope = serde_json::from_str(parsed.wire.get()).expect("wire envelope");
        let envelope = Envelope::try_from(wire)
            .unwrap_or_else(|e| panic!("{name}/{}: shape: {e}", parsed.label));
        if parsed.label == "node.genesis" {
            pubkey = Some(envelope.genesis_pubkey().expect("genesis pubkey"));
        }
        // R12: the canonical bytes re-derived from the decoded envelope are
        // the frozen bytes, and the hash and signature are over them.
        assert_eq!(
            hex(&envelope.canonical_bytes()),
            parsed.canonical,
            "{name}/{}: canonical bytes changed",
            parsed.label
        );
        assert_eq!(
            sha256_hex(&envelope.canonical_bytes()),
            hex(&envelope.hash),
            "{name}/{}: hash is not SHA-256 of the canonical bytes",
            parsed.label
        );
        assert!(
            FactRegistry::builtins()
                .lookup(&envelope.kind, envelope.kind_version)
                .is_some(),
            "{name}/{}: ({}, {}) is not registered",
            parsed.label,
            envelope.kind,
            envelope.kind_version
        );
        decode_payload(&envelope.kind, &envelope.payload)
            .unwrap_or_else(|e| panic!("{name}/{}: payload: {e}", parsed.label));
        kinds.insert((envelope.kind.clone(), envelope.kind_version));
        labels.push(parsed.label);
        envelopes.push(envelope);
    }
    let pubkey = pubkey.unwrap_or_else(|| panic!("{name}: no node.genesis envelope"));
    for envelope in envelopes.iter().chain(from_frames) {
        envelope.verify(&pubkey).unwrap_or_else(|e| {
            panic!(
                "{name}: {} #{} verify: {e}",
                envelope.kind, envelope.counter
            )
        });
    }
    let variant = envelopes
        .iter()
        .zip(&labels)
        .find(|(_, label)| label.as_str() == peer_wire_freeze::NO_AUTHOR_ROLE)
        .unwrap_or_else(|| panic!("{name}: no {} line", peer_wire_freeze::NO_AUTHOR_ROLE))
        .0;
    let payload: serde_json::Value = serde_json::from_slice(&variant.payload).expect("payload");
    assert!(
        payload.get("author_role").is_none(),
        "{name}: the variant carries author_role"
    );
    let typed: message::MessageSentPayload =
        serde_json::from_slice(&variant.payload).expect("variant decodes");
    assert_eq!(typed.author_role, None, "{name}: variant author_role");
    kinds
}

#[test]
fn every_fixture_dir_decodes() {
    let dirs = fixture_dirs();
    let names: Vec<String> = dirs.iter().map(|d| name_of(d)).collect();
    for required in ["2.0.4", "2.1.1"] {
        assert!(
            names.iter().any(|n| n == required),
            "fixture dir {required} is missing (have {names:?})"
        );
    }
    for dir in &dirs {
        let name = name_of(dir);
        let from_frames = check_session(dir);
        let kinds = check_envelopes(dir, &from_frames);
        let manifest = std::fs::read_to_string(dir.join("MANIFEST.md")).expect("MANIFEST.md");
        assert_eq!(
            kinds,
            manifest_kinds(&manifest),
            "{name}: fact kinds in envelopes.jsonl differ from MANIFEST.md"
        );
        for (kind, major) in &kinds {
            assert!(
                PARKED.contains(&(kind.as_str(), *major))
                    || FactRegistry::builtins().lookup(kind, *major).is_some(),
                "{name}: ({kind}, {major}) is not registered in this build"
            );
        }
    }
}

#[test]
fn fixture_files_match_manifest_hashes() {
    for dir in fixture_dirs() {
        let name = name_of(&dir);
        let manifest = std::fs::read_to_string(dir.join("MANIFEST.md")).expect("MANIFEST.md");
        let listed = manifest_files(&manifest);
        for required in ["session.jsonl", "envelopes.jsonl"] {
            assert!(
                listed.iter().any(|(_, file)| file == required),
                "{name}: MANIFEST.md does not list {required}"
            );
        }
        for (hash, file) in &listed {
            let bytes = std::fs::read(dir.join(file))
                .unwrap_or_else(|e| panic!("tests/fixtures/peer_wire/{name}/{file}: {e}"));
            assert_eq!(
                &sha256_hex(&bytes),
                hash,
                "tests/fixtures/peer_wire/{name}/{file} changed: fixtures are append-only; \
                 add a new version dir with scripts/freeze-peer-wire instead"
            );
        }
        for entry in std::fs::read_dir(&dir).expect("fixture dir") {
            let file = entry
                .expect("entry")
                .file_name()
                .to_string_lossy()
                .into_owned();
            assert!(
                file == "MANIFEST.md" || listed.iter().any(|(_, listed)| *listed == file),
                "tests/fixtures/peer_wire/{name}/{file} is not listed in MANIFEST.md"
            );
        }
    }
}

#[test]
fn generator_kind_table_covers_builtins() {
    assert_eq!(
        peer_wire_freeze::KINDS.len(),
        FactRegistry::builtins().len(),
        "a builtin kind is missing from the freeze generator's KINDS"
    );
    for (name, major) in peer_wire_freeze::KINDS {
        assert!(
            FactRegistry::builtins().lookup(name, *major).is_some(),
            "generator kind ({name}, {major}) is not registered"
        );
    }
}

#[test]
fn generator_writes_both_files() {
    use herdr_threads::test_support::scratch::temp_path;
    let first = temp_path(format!("peer-wire-freeze-a-{}", std::process::id()));
    let second = temp_path(format!("peer-wire-freeze-b-{}", std::process::id()));
    peer_wire_freeze::write_fixture(&first);
    peer_wire_freeze::write_fixture(&second);
    for file in ["session.jsonl", "envelopes.jsonl", "kinds.txt"] {
        let a = std::fs::read(first.join(file)).expect(file);
        assert!(!a.is_empty(), "{file} is empty");
        assert_eq!(
            a,
            std::fs::read(second.join(file)).expect(file),
            "{file} differs between two runs"
        );
    }
}
